# frozen_string_literal: true
require 'json'
require 'date'
require 'digest'
require 'cgi'
require_relative 'guide_inline_links'
require_relative 'guide_ui'
require 'uri'
require 'fileutils'

# Each date is a checked edition, never an inferred annual recurrence.
module EventGuides
  DATA = JSON.parse(File.read(File.expand_path('../_data/event-guides.json', __dir__)))
  PHOTOS = JSON.parse(File.read(File.expand_path('../_data/event-guide-photos.json', __dir__))).fetch('photos')
  GUIDES = DATA.fetch('guides')
  ALIASES = {'staro'=>'/svetki-un-tradicijas/staro-riga/', 'advente'=>'/svetki-un-tradicijas/advente/', 'proklamesana'=>'/svetki-un-tradicijas/latvijas-republikas-proklamesanas-diena/', 'zemes-diena'=>'/svetki-un-tradicijas/zemes-diena/', 'saulgriezi'=>'/svetki-un-tradicijas/saulgriezi/', 'ziemas-saulgriezi'=>'/svetki-un-tradicijas/ziemas-saulgriezi/', 'juras'=>'/svetki-un-tradicijas/juras-svetku-diena/', 'skolas'=>'/skolas-brivlaiki/'}
  module_function
  def find(url); GUIDES.find { |g| g.fetch('url')==url }; end
  def link(slug); ALIASES[slug] || GUIDES.find { |g| g['slug']==slug }&.fetch('url') || raise("Unknown event relationship #{slug}"); end
  def photo(g); PHOTOS.fetch(g.fetch('photo')); end
  def image(g, eager: false)
    p=photo(g)
    %(<img src="#{CGI.escapeHTML(p.fetch('src'))}" srcset="#{CGI.escapeHTML(p.fetch('srcset',p.fetch('src')+' '+p.fetch('width').to_s+'w'))}" sizes="(max-width: 700px) 100vw, 55vw" width="#{p.fetch('width')}" height="#{p.fetch('height')}" alt="#{CGI.escapeHTML(p.fetch('alt'))}" loading="#{eager ? 'eager' : 'lazy'}" #{eager ? 'fetchpriority="high"' : ''} decoding="async">)
  end
  def badge(g);g['pending'] ? 'Nākamā norise vēl jāizziņo' : 'Datums publicēts';end
  def card(g)
    %(<a class="event-card" data-event-card data-city="#{CGI.escapeHTML(g.fetch('city'))}" data-category="#{CGI.escapeHTML(g.fetch('category'))}" href="#{g.fetch('url')}"><div class="event-card-image">#{image(g)}<span>#{CGI.escapeHTML(g.fetch('category'))}</span></div><div class="event-card-copy"><small>#{CGI.escapeHTML(g.fetch('city'))} · #{badge(g)}</small><h3>#{CGI.escapeHTML(g.fetch('title'))}</h3><p>#{CGI.escapeHTML(g.fetch('dateLabel'))}</p><span class="event-card-cta">Atvērt ceļvedi #{GuideUI.icon('external')}</span></div></a>)
  end
  def hub
    months=%w[janvāris februāris marts aprīlis maijs jūnijs jūlijs augusts septembris oktobris novembris decembris]
    groups=GUIDES.reject{|g|g['pending']}.group_by{|g|g['start'][0,7]}.sort
    sections=groups.map do |period,rows|
      year,month=period.split('-').map(&:to_i)
      %(<section class="event-month" data-event-group id="menesis-#{period}"><div class="event-section-title"><span>#{year}</span><h2>#{months[month-1].capitalize}</h2></div><div class="event-grid">#{rows.sort_by{|g|g['start']}.map{|g|card(g)}.join}</div></section>)
    end.join
    pending=GUIDES.select{|g|g['pending']}
    options=->(key){GUIDES.map{|g|g[key]}.uniq.sort.map{|v|%(<option value="#{CGI.escapeHTML(v)}">#{CGI.escapeHTML(v)}</option>)}.join}
    %(<div class="event-guide event-hub" data-events-directory><header class="event-hub-hero"><div><span class="event-kicker">LATVIJA · NOTIKUMI UN VIETAS</span><h1>Nozīmīgas dienas un pasākumi Latvijā</h1><p>Gaismas vakari, pilsētu svētki, mūzika un satikšanās. Atrodi datumus, pārbaudi vietu un izvēlies sev piemērotu maršrutu.</p><div class="event-actions"><a href="#pasakumi" class="event-button event-button--light">Izvēlēties pasākumu</a><a href="#atzimejamas-dienas" class="event-text-link">Svētki un atzīmējamās dienas#{GuideUI.icon('down')}</a></div></div><figure>#{image(GUIDES.first,eager:true)}<figcaption>#{CGI.escapeHTML(photo(GUIDES.first).fetch('caption'))}</figcaption></figure></header><div class="event-hub-intro" id="pasakumi"><div><span class="event-kicker">SĀC AR DATUMU</span><h2>Kurp dosimies?</h2></div><p>2026. gada nogales un 2027. gada ceļveži. Izziņotie datumi sakārtoti secībā. Pasākumi, kuru nākamā norise vēl jāizziņo, ir atsevišķā sadaļā.</p></div><form class="event-filters" role="search" aria-label="Meklēt pasākumu"><label>Nosaukums vai vieta<input type="search" data-event-search placeholder="Piemēram, Jelgava vai maratons"></label><label>Pilsēta<select data-event-city><option value="">Visas vietas</option>#{options.call('city')}</select></label><label>Interese<select data-event-category><option value="">Visas tēmas</option>#{options.call('category')}</select></label><button class="event-button event-button--quiet" type="reset">Notīrīt</button></form><p class="event-result-count" data-event-count role="status" aria-live="polite">#{GUIDES.length} ceļveži</p><div data-event-results>#{sections}<section class="event-month" data-event-group><div class="event-section-title"><h2>Nākamais datums vēl jāizziņo</h2></div><p>Šo notikumu arhīvs palīdz iepazīt norisi; 2026. gada datums nav 2027. gada solījums.</p><div class="event-grid">#{pending.map{|g|card(g)}.join}</div></section></div><p class="event-empty" data-event-empty hidden>Šādai izvēlei ceļveža vēl nav. Izmēģini citu pilsētu vai notīri filtrus.</p><section class="event-note"><h2>Pasākums nav automātiska brīvdiena</h2><p>Festivāls, izstāde un tradīciju vakars pats par sevi nemaina darba grafiku. <a href="/svetku-dienas/">Latvijas svētku brīvdienas</a> pārbaudi atsevišķi. Zemāk atrodams arī <a href="#atzimejamas-dienas">atzīmējamo dienu pārskats</a> ar saitēm uz tradīciju skaidrojumiem.</p></section></div>)
  end
  def hero_visual(g)
    p=photo(g);h=->(s){CGI.escapeHTML(s.to_s)}
    d=Date.iso8601(g.fetch('start')); months=%w[JAN FEB MAR APR MAI JŪN JŪL AUG SEP OKT NOV DEC]
    date=%(<div class="guide-date-ticket"><span>#{g['pending'] ? 'ARHĪVA DATUMS' : 'SAGLABĀ DATUMU'}</span><strong>#{d.day.to_s.rjust(2,'0')}</strong><div><b>#{months[d.month-1]}</b><small>#{d.year}</small></div>#{GuideUI.icon('calendar')}</div>)
    unless g['shopping']
      return %(<div class="event-visual"><figure class="event-hero-photo">#{image(g,eager:true)}<figcaption>#{h.call(p.fetch('caption'))} <a href="/pilsetas-un-fotografijas/#pasakumu-foto">Foto licence</a></figcaption></figure><span class="event-location-tag">#{GuideUI.icon('location')}#{h.call(g.fetch('city'))}</span>#{date}</div>)
    end
    friday=g['slug']=='melna-piektdiena'
    %(<div class="shopping-studio"><div class="shopping-studio-label">#{GuideUI.icon('bag')}<span>GUDRA PIRKUMA CEĻVEDIS</span><span>LV / 2026</span></div><div class="shopping-workspace" role="img" aria-label="Salīdzinājuma shēma: preces cenai pieskaita piegādi, lai salīdzinātu gala cenu."><div class="studio-orbit"></div><div class="shopping-laptop"><div class="laptop-screen"><div class="screen-toolbar"><span></span><span></span><span></span><b>CENAS SALĪDZINĀJUMS</b></div><div class="screen-product"><div class="screen-product-art">#{GuideUI.icon('bag')}</div><div><small>VIENA UN TĀ PATI PRECE</small><strong>Salīdzini kopējo cenu.</strong><span class="screen-line"></span><span class="screen-line screen-line--short"></span></div></div><div class="screen-equation"><span>Prece</span><b>+</b><span>Piegāde</span><b>=</b><strong>Gala cena</strong></div></div><div class="laptop-base"></div></div><div class="shopping-receipt"><span>PIRMS APMAKSAS</span><b>Pirkuma pārbaude</b><div>#{GuideUI.icon('check')}Tas pats modelis</div><div>#{GuideUI.icon('check')}Piegāde iekļauta</div><div>#{GuideUI.icon('check')}Zināms pārdevējs</div><footer>Salīdzini. Tad izvēlies.</footer></div>#{date}</div><nav class="shopping-date-switch" aria-label="Iepirkšanās dienas"><a href="/pasakumi/melna-piektdiena/"#{friday ? ' aria-current="page"' : ''}><b>27</b><span>NOV<small>Melnā piektdiena</small></span></a><a href="/pasakumi/kiberpirmdiena/"#{friday ? '' : ' aria-current="page"'}><b>30</b><span>NOV<small>Kiberpirmdiena</small></span></a></nav></div>)
  end
  def page(g)
    h=->(s){CGI.escapeHTML(s.to_s)};p=photo(g);map=g['mapQuery'] && 'https://www.google.com/maps/search/?api=1&query='+URI.encode_www_form_component(g['mapQuery'])
    date_link='/?'+URI.encode_www_form(date:g.fetch('start'),view:'day')
    related=g.fetch('related').map{|id|find(link(id))}.compact
    calendar=g['pending'] ? '' : %(<a class="event-button" href="/kalendari/pasakumi/#{g.fetch('slug')}.ics" download>#{GuideUI.icon('calendar')}Pievienot kalendāram</a>)
    sections=g.fetch('sections').each_with_index.map{|s,i|%(<section class="event-chapter" id="nodala-#{i+1}"><span class="event-chapter-number">#{format('%02d',i+1)}</span><div><h2>#{h.call(s.fetch('title'))}</h2><p>#{GuideInlineLinks.render(s.fetch('text'),g.fetch('url'),i)}</p></div></section>)}.join
    %(<article class="event-guide#{g['shopping'] ? ' event-guide--shopping' : ''}" data-event-guide="#{g.fetch('slug')}"><header class="event-hero"><div class="event-hero-copy"><span class="event-kicker"><span class="guide-category-symbol">#{GuideUI.icon(g['shopping'] ? 'bag' : 'calendar')}</span>#{h.call(g.fetch('city'))} / #{h.call(g.fetch('category'))}</span><h1>#{h.call(g['shopping'] ? (g['slug']=='melna-piektdiena' ? 'Melnā piektdiena Latvijā' : 'Kiberpirmdiena Latvijā') : g.fetch('title'))}</h1><span class="guide-edition">#{g['pending'] ? 'Iepriekšējās norises ceļvedis' : Date.iso8601(g.fetch('start')).year.to_s+' · DATUMI UN PRAKTISKS CEĻVEDIS'}</span><p>#{h.call(g.fetch('intro'))}</p><div class="event-actions"><a class="event-button event-button--light" href="#{g['shopping'] ? '#veikali' : '#datumi'}">#{g['shopping'] ? 'Salīdzināt piedāvājumus' : 'Datumi un vieta'} #{GuideUI.icon('arrow')}</a><a class="event-text-link" href="#{g['shopping'] ? '#cenu-kalkulators' : '#apmeklejums'}">#{g['shopping'] ? 'Cenu kalkulators' : 'Plānot apmeklējumu'} #{GuideUI.icon('down')}</a></div></div>#{hero_visual(g)}</header><nav class="event-subnav" aria-label="Ceļveža sadaļas"><a href="#datumi">Datums</a><a href="#apmeklejums">#{g['shopping'] ? 'Pirkuma izvēle' : 'Apmeklējums'}</a><a href="#pirms-cela">#{g['shopping'] ? 'Pirms pirkuma' : 'Pirms ceļa'}</a><a href="#nakamie-gadi">2026–2030</a></nav><section class="event-facts" id="datumi" aria-label="Norises informācija"><div class="event-date-block"><span class="event-date-status">#{badge(g)}</span><small>#{h.call(g.fetch('whenQuestion'))}</small><strong>#{h.call(g.fetch('dateLabel'))}</strong><span>#{h.call(g.fetch('time'))}</span>#{g['pending'] ? '<p>Iepriekšējā norise: '+h.call(g.fetch('start'))+'.</p>' : '<time datetime="'+g.fetch('start')+'">Latvijas laiks · Europe/Riga</time>'}</div><div><small>#{GuideUI.icon('location')} #{h.call(g.fetch('whereQuestion'))}</small><h2>#{h.call(g.fetch('place'))}</h2>#{map ? %(<a href="#{map}" class="event-inline-link" rel="noopener">Apskatīt vietu kartē#{GuideUI.icon('external')}</a>) : %(<a href="#{h.call(g.fetch('sources').first.fetch('url'))}" class="event-inline-link" rel="noopener">#{g['shopping'] ? 'Atvērt veikala kampaņu' : 'Vietas rīkotāja programmā'}#{GuideUI.icon('external')}</a>)}</div><div><small>#{g['shopping'] ? 'Pirkuma nosacījumi' : 'Ieeja un biļetes'}</small><p>#{h.call(g.fetch('admission'))}</p><a href="#{h.call(g.fetch('sources').first.fetch('url'))}" class="event-inline-link" rel="noopener">#{g['shopping'] ? 'Pārbaudīt piedāvājumu' : 'Atvērt rīkotāja informāciju'}#{GuideUI.icon('external')}</a></div></section><div class="event-editorial" id="apmeklejums"><div class="event-chapters">#{sections}</div><aside class="event-aside"><span class="event-kicker">#{g['shopping'] ? 'PIRMS PIRKUMA' : 'PIRMS CEĻA'}</span><h2>Trīs lietas, ko pārbaudīt</h2><ol>#{g.fetch('checklist').map{|item|"<li>#{h.call(item)}</li>"}.join}</ol><div class="event-aside-actions">#{calendar}<a class="event-button event-button--quiet" href="#{date_link}">#{g['pending'] ? 'Apskatīt arhīva datumu' : 'Atvērt dienas plānu'}</a></div><p class="event-fineprint">#{g['pending'] ? 'Jaunās sezonas kalendāra fails būs pieejams pēc datuma izziņošanas. Arhīva datumu neizmanto nākamās norises plānošanai.' : (g['startsAt'] ? 'Ieraksts ar norādīto sākuma un beigu laiku.' : 'Visas dienas ieraksts; precīzās stundas ir aprakstā.')+' Fails ir vienreizēja kopija, kas neatjaunojas automātiski. Atgādinājumu iestati savā lietotnē.'}</p></aside></div>#{shopping_content(g)}#{experience(g)}#{edition_dates(g)}#{questions(g)}<section class="event-note" id="pirms-cela"><span class="event-kicker">#{g['shopping'] ? 'PIRMS PASŪTĪJUMA' : 'PIRMS DOŠANĀS'}</span><h2>#{g['shopping'] ? 'Lēmums pēc vajadzības un gala cenas' : 'Atstāj vietu pašam piedzīvojumam'}</h2><p>#{h.call(g.fetch('closing'))}</p></section><nav class="event-topic-links" aria-label="Saistītās tēmas"><strong>Saistītās tēmas</strong>#{g.fetch('related').select{|id|ALIASES.key?(id)}.map{|id|%(<a href="#{link(id)}">#{h.call({'staro'=>'Staro Rīga','advente'=>'Advente','proklamesana'=>'18. novembra nozīme','zemes-diena'=>'Zemes diena','saulgriezi'=>'Saulgrieži','ziemas-saulgriezi'=>'Ziemas saulgrieži','juras'=>'Jūras svētku diena','skolas'=>'Skolas brīvlaiki'}.fetch(id))}</a>)}.join}</nav></article>)
  end
  def experience(g)
    h=->(s){CGI.escapeHTML(s.to_s)}
    steps=g.fetch('visitPlan').each_with_index.map { |s,i| %(<li><span class="event-plan-step" aria-hidden="true">#{i+1}</span><h3>#{h.call(s.fetch('label'))}</h3><p>#{h.call(s.fetch('text'))}</p></li>) }.join
    %(<section class="event-visit-plan" aria-labelledby="event-plan-title"><div class="event-plan-heading"><div><span class="event-kicker">#{g['shopping'] ? 'PIRKUMA PLĀNS' : 'TAVS APMEKLĒJUMA PLĀNS'}</span><h2 id="event-plan-title">#{g['shopping'] ? 'Trīs soļi pārdomātai izvēlei' : 'Kā salikt savu dienu'}</h2></div><p>#{g['shopping'] ? 'Praktiska salīdzināšanas secība. Veikalu cenas un atlikumi jāpārbauda pirkuma brīdī.' : 'Ieteikta plānošanas secība, nevis rīkotāja stundu programma. Precīzu laiku pārbaudi pie izvēlētās norises.'}</p></div><ol>#{steps}</ol></section><section class="event-status-grid" aria-label="Programmas gatavība"><div><span class="event-status-dot" aria-hidden="true"></span><h2>#{g['pending'] ? 'Kas zināms par arhīva piemēru' : 'Avotos norādītais'}</h2><ul>#{g.fetch('confirmed').map{|s|"<li>#{h.call(s)}</li>"}.join}</ul></div><div><span class="event-status-dot event-status-dot--wait" aria-hidden="true"></span><h2>Pirms plāna apstiprināšanas</h2><ul>#{g.fetch('toCheck').map{|s|"<li>#{h.call(s)}</li>"}.join}</ul><p>#{g['pending'] ? 'Nākamās sezonas datumu neaprēķinām no iepriekšējā gada. Sagaidi Latvijas rīkotāja paziņojumu.' : (g['shopping'] ? 'Kampaņas datums nav garantija zemākajai cenai. Pārbaudi konkrēto preci un pasūtījuma noteikumus.' : 'Publicēts datums nenozīmē, ka jau zināma katra aktivitāte, biļetes cena vai transporta izmaiņa.')}</p></div></section>)
  end
  def questions(g)
    %(<section class="event-faq"><span class="event-kicker">PIRMS IZVĒLES</span><h2>Bieži jautājumi</h2>#{(g.fetch('quickAnswers')+g.fetch('faq')).map{|f|%(<details><summary>#{CGI.escapeHTML(f.fetch('question'))}</summary><p>#{CGI.escapeHTML(f.fetch('answer'))}</p></details>)}.join}</section>)
  end
  def edition_dates(g)
    rows=g.fetch('editionDates').map do |row|
      %(<tr><th scope="row">#{row.fetch('year')}</th><td>#{CGI.escapeHTML(row.fetch('date'))}</td><td>#{CGI.escapeHTML(row.fetch('status'))}</td></tr>)
    end.join
    %(<section class="event-editions" id="nakamie-gadi"><div class="event-editions-heading"><div><span class="event-kicker">PLĀNO VAIRĀKUS GADUS UZ PRIEKŠU</span><h2>#{CGI.escapeHTML(g.fetch('dateOverviewTitle'))}</h2></div>#{GuideUI.icon('calendar')}</div><p>#{g['shopping'] ? 'Kalendāra datums nenosaka akciju ilgumu vai atlaides. Katrs tirgotājs publicē savus nosacījumus.' : 'Datumu nepārnesam no iepriekšējās sezonas. Tabulā atšķirti publicētie datumi un gadi, kuriem šajā ceļvedī nav apstiprinājuma.'}</p><div class="event-editions-table"><table><caption>Datumu pārskats, pārbaudīts 15.11.2026.</caption><thead><tr><th scope="col">Gads</th><th scope="col">Datums</th><th scope="col">Kas jāņem vērā</th></tr></thead><tbody>#{rows}</tbody></table></div><a class="event-inline-link" href="#{CGI.escapeHTML(g.fetch('sources').first.fetch('url'))}">Pārbaudīt jaunāko informāciju avotā #{GuideUI.icon('external')}</a></section>)
  end
  def shopping_content(g)
    return '' unless g['shopping']
    history=if g['slug']=='melna-piektdiena'
      %(<section class="event-shopping-history"><span class="event-kicker">2025. GADA ARHĪVS · NAV AKTUĀLAS CENAS</span><h2>Ko piedāvāja pagājušajā gadā?</h2><div class="event-shopping-table"><table><caption>Tirgotāju publicētie 2025. gada akciju noteikumi; tirgus zemākā cena nav pārbaudīta.</caption><thead><tr><th scope="col">Tirgotājs</th><th scope="col">Reklamētais piedāvājums</th><th scope="col">Termiņš un ierobežojumi</th></tr></thead><tbody><tr><th scope="row"><a href="https://www.davanuserviss.lv/melna-piektdiena-2025-noteikumi/">Dāvanu Serviss</a></th><td>20% atlasītiem piedāvājumiem</td><td>28.11.–01.12.2025. Nesummēja ar citām akcijām; nomināla kartes un daļa pakalpojumu sniedzēju bija izslēgti.</td></tr><tr><th scope="row"><a href="https://vincento.lv/gada-lielaka-izpardosana-melna-piektdiena-2025/">Vincento</a></th><td>40% atbilstošām precēm</td><td>24.–30.11.2025. Veikalā un internetā; jau nocenotās preces akcijā neietilpa.</td></tr></tbody></table></div><p>Šie procenti ir vēsturiski nosacījumi, nevis 2026. gada solījums. Aktuālo kuponu pārbaudi pie tirgotāja.</p></section>)
    else
      %(<section class="event-shopping-history"><span class="event-kicker">NO PIEKTDIENAS LĪDZ PIRMDIENAI</span><h2>Ko pierakstīt, pirms mainās akcijas lapa?</h2><p>Preces modeļa kodu, pārdevēju, datumu, cenu ar PVN, piegādi un kupona noteikumus. 2025. gada Dāvanu Serviss kampaņa turpinājās līdz pirmdienai, bet tas nenozīmē, ka pirmdien pievienojās vēl 20% atlaide. Salīdzini gala cenu, nevis saskaiti divus reklāmas procentus.</p></section>)
    end
