  def notes(url)
    g=find(url)
    g ? {'heading'=>'Ceļveža lietošana','paragraphs'=>[g.fetch('intro'),g.fetch('closing')+' '+g.fetch('sections').last.fetch('text')],'icon'=>'calendar','sources'=>g.fetch('sources'),'related'=>g.fetch('related').map{|s|{'url'=>link(s),'title'=>find(link(s))&.fetch('title') || s}}} : {'heading'=>'Notikuma izvēle','paragraphs'=>['Ceļveži apvieno norises datumu, vietu un apmeklējuma plānu. Pie katra redzams, vai nākamā programma jau ir publicēta.','Izvēlies notikumu un pirms ceļa atver rīkotāja avotu. Festivāla datums pats par sevi nav darba brīvdiena.'],'icon'=>'calendar','sources'=>[],'related'=>[{'url'=>'/svetki-un-tradicijas/','title'=>'Svētki un tradīcijas'}]}
  end
  def calendar_records
    result=GUIDES.reject { |g| g['pending'] }.map do |g|
      {'id'=>"public-#{g.fetch('slug')}",'title'=>g.fetch('title'),'date'=>g.fetch('start'),'end'=>g['end'] || g.fetch('start'),'url'=>g.fetch('url'),'place'=>g.fetch('place'),'schedule'=>g.fetch('time'),'category'=>'event','readonly'=>true,'publicEvent'=>true,'dayOff'=>false}
    end
    staro=JSON.parse(File.read(File.expand_path('../_data/staro-riga.json', __dir__)))
    result << {'id'=>'public-staro-riga','title'=>'Staro Rīga 2026','date'=>staro.fetch('startDate'),'end'=>staro.fetch('endDate'),'url'=>'/svetki-un-tradicijas/staro-riga/','place'=>'Gaismas objekti Rīgā','schedule'=>"Katru vakaru #{staro.fetch('startTime')}–#{staro.fetch('endTime')}",'category'=>'event','readonly'=>true,'publicEvent'=>true,'dayOff'=>false}
    result
  end
  def calendars
    FileUtils.mkdir_p('kalendari/pasakumi')
    GUIDES.reject{|g|g['pending']}.each do |g|
      escape=->(s){s.to_s.gsub('\\','\\\\').gsub("\n",'\\n').gsub(';','\\;').gsub(',','\\,')}
      finish=Date.iso8601(g['end'] || g.fetch('start'))+1
      lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Kalendars365.lv//Events//LV','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT',"UID:#{g['slug']}-#{g['start']}@kalendars365.lv",'DTSTAMP:20261115T180000Z',*(g['startsAt'] ? ["DTSTART:#{g['startsAt']}","DTEND:#{g['endsAt']}"] : ["DTSTART;VALUE=DATE:#{g['start'].delete('-')}","DTEND;VALUE=DATE:#{finish.strftime('%Y%m%d')}"]),"SUMMARY:#{escape.call(g['title'])}","LOCATION:#{escape.call(g['place'])}","DESCRIPTION:#{escape.call(g['time']+'. '+g['sources'].first['url'])}","URL:https://kalendars365.lv#{g['url']}",'TRANSP:TRANSPARENT','END:VEVENT','END:VCALENDAR']
      folded=lines.flat_map{|line| chunks=[];part='';line.each_char{|c|if part.bytesize+c.bytesize>75;chunks<<part;part=' ';end;part+=c};chunks<<part}
      File.binwrite("kalendari/pasakumi/#{g['slug']}.ics",folded.join("\r\n")+"\r\n")
    end
  end
end
